Malware         Signature
        NanoCore alert tcp any any -> any $HTTP_PORTS (msg:"NANOCORE:HTTP GET URI
                 contains 'FAD00979338'"; sid:00000000; rev:1;
                 flow:established,to_server; content:"GET"; http_method;
                 content:"getPluginName.php?PluginID=FAD00979338"; fast_pattern;
                 http_uri; classtype:http-uri; metadata:service http;)
        Cerber          alert tcp any any -> any $HTTP_PORTS (msg:"HTTP Client Header
                        contains 'host|3a 20|polkiuj.top'"; sid:00000000; rev:1;
                        flow:established,to_server; flowbits:isnotset,<unique_ID>.tagged;
                        content:"host|3a 20|polkiuj.top|0d 0a|"; http_header;
                        fast_pattern:only; flowbits:set,<unique_ID>.tagged;
                        tag:session,10,packets; classtype:http-header; metadata:service
                        http;)
        Kovter          alert tcp any any -> any $HTTP_PORTS (msg:"Kovter:HTTP URI POST to
                        CnC Server"; sid:00000000; rev:1; flow:established,to_server;
                        flowbits:isnotset,<unique_ID>.tagged; content:"POST / HTTP/1.1";
                        depth:15; content:"Content-Type|3a 20|application/x-www-form-
                        urlencoded"; http_header; depth:47; fast_pattern; content:"User-
                        Agent|3a 20|Mozilla/"; http_header; content:!"LOADCURRENCY"; nocase;
                        content:!"Accept"; http_header; content:!"Referer|3a|"; http_header;
                        content:!"Cookie|3a|"; nocase; http_header; pcre:"/^(?:[A-Za-z0-
                        9+\/]{4})*(?:[A-Za-z0-9+\/]{2}==|[A-Za-z0-9+\/]{3}=|[A-Za-z0-
                        9+\/]{4})$/P"; pcre:"/User-
                        Agent\x3a[^\r\n]+\r\nHost\x3a\x20(?:\d{1,3}\.){3}\d{1,3}\r\nContent-
                        Length\x3a\x20[1-5][0-9]{2,3}\r\n(?:Cache-
                        Control|Pragma)\x3a[^\r\n]+\r\n(?:\r\n)?$/H";
                        flowbits:set,<unique_ID>.tagged; tag:session,10,packets;
                        classtype:nonstd-tcp; metadata:service http;)

Dridex          alert tcp any any -> any $HTTP_PORTS (msg:"HTTP URI GET contains
                        'invoice_########.doc' (DRIDEX)"; sid:00000000; rev:1;
                        flow:established,to_server; content:"invoice_"; http_uri;
                        fast_pattern:only; content:".doc"; nocase; distance:8; within:4;
                        content:"GET"; nocase; http_method; classtype:http-uri;
                        metadata:service http;)
                        alert tcp any any -> any $HTTP_PORTS (msg:"HTTP Client Header
                        contains 'Host|3a 20|tanevengledrep ru' (DRIDEX)"; sid:00000000;
                        rev:1; flow:established,to_server;
                        flowbits:isnotset,<unique_ID>.tagged; content:"Host|3a
                        20|tanevengledrep|2e|ru|0d 0a|"; http_header; fast_pattern:only;
                        flowbits:set,<unique_ID>.tagged; tag:session,10,packets;
                        classtype:http-header; metadata:service http;)
